Sub 'PrintFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'PRODPROGRAMA' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodPrograma1.FromString(&GridStateDynamicFilter.Value) If not &prodPrograma1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", "<") Case &DynamicFiltersOperator1 = 1 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", "=") Case &DynamicFiltersOperator1 = 2 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", ">") EndCase &prodPrograma = &prodPrograma1 print printBlockFilterprodPrograma EndIf Case &DynamicFiltersSelector1 = !'PRODCODIGO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodCodigo1.FromString(&GridStateDynamicFilter.Value) If not &prodCodigo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterprodCodigoDescription = format('%1 (%2)', "Código", "<") Case &DynamicFiltersOperator1 = 1 &FilterprodCodigoDescription = format('%1 (%2)', "Código", "=") Case &DynamicFiltersOperator1 = 2 &FilterprodCodigoDescription = format('%1 (%2)', "Código", ">") EndCase &prodCodigo = &prodCodigo1 print printBlockFilterprodCodigo EndIf Case &DynamicFiltersSelector1 = !'PRODDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodDescricao1.FromString(&GridStateDynamicFilter.Value) If not &prodDescricao1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterprodDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &FilterprodDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &prodDescricao = &prodDescricao1 print printBlockFilterprodDescricao EndIf Case &DynamicFiltersSelector1 = !'PRODSALDO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodSaldo1.FromString(&GridStateDynamicFilter.Value) If not &prodSaldo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", "<") Case &DynamicFiltersOperator1 = 1 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", "=") Case &DynamicFiltersOperator1 = 2 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", ">") EndCase &prodSaldo = &prodSaldo1 print printBlockFilterprodSaldo EndIf Case &DynamicFiltersSelector1 = !'PRODTIPO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &prodTipo1.FromString(&GridStateDynamicFilter.Value) If not &prodTipo1.IsEmpty() Do Case Case &DynamicFiltersOperator1 = 0 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", "<") Case &DynamicFiltersOperator1 = 1 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", "=") Case &DynamicFiltersOperator1 = 2 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", ">") EndCase &prodTipo = &prodTipo1 print printBlockFilterprodTipo EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'PRODPROGRAMA' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodPrograma2.FromString(&GridStateDynamicFilter.Value) If not &prodPrograma2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", "<") Case &DynamicFiltersOperator2 = 1 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", "=") Case &DynamicFiltersOperator2 = 2 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", ">") EndCase &prodPrograma = &prodPrograma2 print printBlockFilterprodPrograma EndIf Case &DynamicFiltersSelector2 = !'PRODCODIGO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodCodigo2.FromString(&GridStateDynamicFilter.Value) If not &prodCodigo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterprodCodigoDescription = format('%1 (%2)', "Código", "<") Case &DynamicFiltersOperator2 = 1 &FilterprodCodigoDescription = format('%1 (%2)', "Código", "=") Case &DynamicFiltersOperator2 = 2 &FilterprodCodigoDescription = format('%1 (%2)', "Código", ">") EndCase &prodCodigo = &prodCodigo2 print printBlockFilterprodCodigo EndIf Case &DynamicFiltersSelector2 = !'PRODDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodDescricao2.FromString(&GridStateDynamicFilter.Value) If not &prodDescricao2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterprodDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &FilterprodDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &prodDescricao = &prodDescricao2 print printBlockFilterprodDescricao EndIf Case &DynamicFiltersSelector2 = !'PRODSALDO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodSaldo2.FromString(&GridStateDynamicFilter.Value) If not &prodSaldo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", "<") Case &DynamicFiltersOperator2 = 1 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", "=") Case &DynamicFiltersOperator2 = 2 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", ">") EndCase &prodSaldo = &prodSaldo2 print printBlockFilterprodSaldo EndIf Case &DynamicFiltersSelector2 = !'PRODTIPO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &prodTipo2.FromString(&GridStateDynamicFilter.Value) If not &prodTipo2.IsEmpty() Do Case Case &DynamicFiltersOperator2 = 0 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", "<") Case &DynamicFiltersOperator2 = 1 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", "=") Case &DynamicFiltersOperator2 = 2 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", ">") EndCase &prodTipo = &prodTipo2 print printBlockFilterprodTipo EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'PRODPROGRAMA' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodPrograma3.FromString(&GridStateDynamicFilter.Value) If not &prodPrograma3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", "<") Case &DynamicFiltersOperator3 = 1 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", "=") Case &DynamicFiltersOperator3 = 2 &FilterprodProgramaDescription = format('%1 (%2)', "Programa", ">") EndCase &prodPrograma = &prodPrograma3 print printBlockFilterprodPrograma EndIf Case &DynamicFiltersSelector3 = !'PRODCODIGO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodCodigo3.FromString(&GridStateDynamicFilter.Value) If not &prodCodigo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterprodCodigoDescription = format('%1 (%2)', "Código", "<") Case &DynamicFiltersOperator3 = 1 &FilterprodCodigoDescription = format('%1 (%2)', "Código", "=") Case &DynamicFiltersOperator3 = 2 &FilterprodCodigoDescription = format('%1 (%2)', "Código", ">") EndCase &prodCodigo = &prodCodigo3 print printBlockFilterprodCodigo EndIf Case &DynamicFiltersSelector3 = !'PRODDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodDescricao3.FromString(&GridStateDynamicFilter.Value) If not &prodDescricao3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterprodDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &FilterprodDescricaoDescription = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &prodDescricao = &prodDescricao3 print printBlockFilterprodDescricao EndIf Case &DynamicFiltersSelector3 = !'PRODSALDO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodSaldo3.FromString(&GridStateDynamicFilter.Value) If not &prodSaldo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", "<") Case &DynamicFiltersOperator3 = 1 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", "=") Case &DynamicFiltersOperator3 = 2 &FilterprodSaldoDescription = format('%1 (%2)', "Saldo", ">") EndCase &prodSaldo = &prodSaldo3 print printBlockFilterprodSaldo EndIf Case &DynamicFiltersSelector3 = !'PRODTIPO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &prodTipo3.FromString(&GridStateDynamicFilter.Value) If not &prodTipo3.IsEmpty() Do Case Case &DynamicFiltersOperator3 = 0 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", "<") Case &DynamicFiltersOperator3 = 1 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", "=") Case &DynamicFiltersOperator3 = 2 &FilterprodTipoDescription = format('%1 (%2)', "Tipo", ">") EndCase &prodTipo = &prodTipo3 print printBlockFilterprodTipo EndIf EndCase EndIf EndIf EndIf If not (&TFprodQtdeMinimo.IsEmpty() AND &TFprodQtdeMinimo_To.IsEmpty()) print printBlockTFprodQtdeMinimo &TFprodQtdeMinimo_To_Description = format('%1 (%2)', "Mínimo", "WWP_TSTo") print printBlockTFprodQtdeMinimo_To EndIf If not (&TFprodSaldo.IsEmpty() AND &TFprodSaldo_To.IsEmpty()) print printBlockTFprodSaldo &TFprodSaldo_To_Description = format('%1 (%2)', "Saldo", "WWP_TSTo") print printBlockTFprodSaldo_To EndIf If not (&TFprodQtdeMaximo.IsEmpty() AND &TFprodQtdeMaximo_To.IsEmpty()) print printBlockTFprodQtdeMaximo &TFprodQtdeMaximo_To_Description = format('%1 (%2)', "Máximo", "WWP_TSTo") print printBlockTFprodQtdeMaximo_To EndIf If not (&TFprodCodigo.IsEmpty() AND &TFprodCodigo_To.IsEmpty()) print printBlockTFprodCodigo &TFprodCodigo_To_Description = format('%1 (%2)', "Código", "WWP_TSTo") print printBlockTFprodCodigo_To EndIf If not &TFprodDescricao_Sel.IsEmpty() print printBlockTFprodDescricao_Sel Else If not &TFprodDescricao.IsEmpty() print printBlockTFprodDescricao EndIf EndIf If not &TFprodUnidMedCompra_Sel.IsEmpty() print printBlockTFprodUnidMedCompra_Sel Else If not &TFprodUnidMedCompra.IsEmpty() print printBlockTFprodUnidMedCompra EndIf EndIf If not &TFprodTipo_Sel.IsEmpty() print printBlockTFprodTipo_Sel Else If not &TFprodTipo.IsEmpty() print printBlockTFprodTipo EndIf EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'PrintColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
print printBlockBeforeGrid print printBlockLines_titles
