EndSub
Sub 'PrintData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsprodutos order prodPrograma when &OrderedBy = 1 order prodDescricao when &OrderedBy = 2 AND &OrderedDsc = False order (prodDescricao) when &OrderedBy = 2 AND &OrderedDsc = True order prodQtdeMinimo when &OrderedBy = 3 AND &OrderedDsc = False order (prodQtdeMinimo) when &OrderedBy = 3 AND &OrderedDsc = True order prodSaldo when &OrderedBy = 4 AND &OrderedDsc = False order (prodSaldo) when &OrderedBy = 4 AND &OrderedDsc = True order prodQtdeMaximo when &OrderedBy = 5 AND &OrderedDsc = False order (prodQtdeMaximo) when &OrderedBy = 5 AND &OrderedDsc = True order prodCodigo when &OrderedBy = 6 AND &OrderedDsc = False order (prodCodigo) when &OrderedBy = 6 AND &OrderedDsc = True order prodUnidMedCompra when &OrderedBy = 7 AND &OrderedDsc = False order (prodUnidMedCompra) when &OrderedBy = 7 AND &OrderedDsc = True order prodTipo when &OrderedBy = 8 AND &OrderedDsc = False order (prodTipo) when &OrderedBy = 8 AND &OrderedDsc = True
using trnsprodutosposicaoWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &prodPrograma1, &prodCodigo1, &prodDescricao1, &prodSaldo1 , &prodTipo1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2, &DynamicFiltersOperator2, &prodPrograma2, &prodCodigo2 , &prodDescricao2, &prodSaldo2, &prodTipo2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &prodPrograma3, &prodCodigo3, &prodDescricao3, &prodSaldo3, &prodTipo3, &TFprodQtdeMinimo , &TFprodQtdeMinimo_To, &TFprodSaldo, &TFprodSaldo_To, &TFprodQtdeMaximo, &TFprodQtdeMaximo_To, &TFprodCodigo , &TFprodCodigo_To, &TFprodDescricao, &TFprodDescricao_Sel, &TFprodUnidMedCompra, &TFprodUnidMedCompra_Sel, &TFprodTipo , &TFprodTipo_Sel) Where prefCodigo = &prefCodigo Where prodStatus = 'A'
Do 'BeforePrintLine' print printBlockLines_data Do 'AfterPrintLine' EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsprodutosposicaoWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsprodutosposicaoWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsprodutosposicaoWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFPRODQTDEMINIMO" &TFprodQtdeMinimo.FromString(&GridStateFilterValue.Value) &TFprodQtdeMinimo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRODSALDO" &TFprodSaldo.FromString(&GridStateFilterValue.Value) &TFprodSaldo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRODQTDEMAXIMO" &TFprodQtdeMaximo.FromString(&GridStateFilterValue.Value) &TFprodQtdeMaximo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRODCODIGO" &TFprodCodigo.FromString(&GridStateFilterValue.Value) &TFprodCodigo_To.FromString(&GridStateFilterValue.ValueTo) Case &GridStateFilterValue.Name = !"TFPRODDESCRICAO" &TFprodDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODDESCRICAO_SEL" &TFprodDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODUNIDMEDCOMPRA" &TFprodUnidMedCompra.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODUNIDMEDCOMPRA_SEL" &TFprodUnidMedCompra_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODTIPO" &TFprodTipo.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFPRODTIPO_SEL" &TFprodTipo_Sel.FromString(&GridStateFilterValue.Value) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
